1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Flags a create as a soft duplicate. Runs before {@link SaveOwner}, so
9	 * {@link OwnerRepository#findAll()} returns only the owners that predate this create. A new owner
10	 * that {@link EnsureIdentityUnique} already cleared as not a hard duplicate is nonetheless a
11	 * <em>possible</em> duplicate when an existing owner shares its normalized lastName and its postcode
12	 * but carries a different telephone. On such a match it sets {@code possibleDuplicate} true and
13	 * {@code possibleDuplicateOf} to the matching owner's id (the lowest id when several match); the
14	 * owner is still created. With no match it sets {@code possibleDuplicate} false and leaves
15	 * {@code possibleDuplicateOf} null.
16	 */
17	public class FlagPossibleDuplicate {
18	
19	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
20	        owner.setPossibleDuplicate(false);
21	        owner.setPossibleDuplicateOf(null);
22	
23	        String postcode = owner.getPostcode();
24	        // A soft match keys on a shared postcode; an owner with no postcode cannot share one.
25	        if (postcode == null || postcode.isBlank()) {
26	            return;
27	        }
28	        String lastName = OwnerIdentity.normalizeName(owner.getLastName());
29	        String telephone = OwnerIdentity.canonicalTelephone(owner.getTelephone());
30	
31	        Owner match = null;
32	        for (Owner existing : ownerRepository.findAll()) {
33	            if (!lastName.equals(OwnerIdentity.normalizeName(existing.getLastName()))) {
34	                continue;
35	            }
36	            if (!postcode.equals(existing.getPostcode())) {
37	                continue;
38	            }
39	            if (telephone.equals(OwnerIdentity.canonicalTelephone(existing.getTelephone()))) {
40	                continue; // same telephone is not the "different telephone" soft match
41	            }
42	            if (match == null || existing.getId() < match.getId()) {
43	                match = existing;
44	            }
45	        }
46	
47	        if (match != null) {
48	            owner.setPossibleDuplicate(true);
49	            owner.setPossibleDuplicateOf(match.getId());
50	        }
51	    }
52	}
