7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName",
22	            expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "initials", expression = "java(initials(owner))")
24	    @Mapping(target = "locality", expression = "java(locality(owner))")
25	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
26	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
27	    @Mapping(target = "membershipLevel",
28	            expression = "java(org.springframework.samples.petclinic.mapper.OwnerMapper.membershipLevel(owner))")
29	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
30	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
31	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
32	    OwnerDto toOwnerDto(Owner owner);
33	
34	    /**
35	     * The owner's age band, computed from {@code birthDate} against {@code registrationDate}:
36	     * {@code MINOR} (under 18), {@code ADULT} (18-64) or {@code SENIOR} (65+). Null when no
37	     * birth date is recorded.
38	     */
39	    default String ageBand(Owner owner) {
40	        if (owner.getBirthDate() == null) {
41	            return null;
42	        }
43	        java.time.LocalDate reference = owner.getRegistrationDate() != null
44	                ? owner.getRegistrationDate() : java.time.LocalDate.now();
45	        int age = java.time.Period.between(owner.getBirthDate(), reference).getYears();
46	        if (age < 18) {
47	            return "MINOR";
48	        }
49	        if (age < 65) {
50	            return "ADULT";
51	        }
52	        return "SENIOR";
53	    }
54	
55	    /**
56	     * The owner's derived {@code identityKey} = normalizedTelephone + '|' + (email or empty) + '|' +
57	     * householdId, the single key all duplicate detection is expressed through.
58	     */
59	    default String identityKey(Owner owner) {
60	        return org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity.key(
61	                owner.getTelephone(), owner.getEmail(), owner.getHouseholdId());
62	    }
63	
64	    /**
65	     * The owner's preferred contact channel: {@code EMAIL} when an email is present, otherwise
66	     * {@code PHONE}.
67	     */
68	    default String contactPreference(Owner owner) {
69	        return owner.getEmail() != null && !owner.getEmail().isBlank() ? "EMAIL" : "PHONE";
70	    }
71	
72	    default String initials(Owner owner) {
73	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
74	                + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
75	    }
76	
77	    /**
78	     * The owner's locality (region), read from the REGION component of the customerCode
79	     * ({@code <REGION>-<HASH8>}); see
80	     * {@link org.springframework.samples.petclinic.rest.function.owner.OwnerRegion#regionOf}.
81	     */
82	    default String locality(Owner owner) {
83	        return org.springframework.samples.petclinic.rest.function.owner.OwnerRegion.regionOf(
84	                owner.getCustomerCode());
85	    }
86	
87	    /**
88	     * A single Luhn check digit (0-9) computed over the digits of the owner's {@code customerCode}.
89	     * Null when the customer code is absent.
90	     */
91	    default Integer checkDigit(Owner owner) {
92	        if (owner.getCustomerCode() == null) {
93	            return null;
94	        }
95	        String code = owner.getCustomerCode();
96	        int sum = 0;
97	        boolean dbl = true;
98	        for (int i = code.length() - 1; i >= 0; i--) {
99	            char c = code.charAt(i);
100	            if (c < '0' || c > '9') {
101	                continue;
102	            }
103	            int d = c - '0';
104	            if (dbl) {
105	                d *= 2;
106	                if (d > 9) {
107	                    d -= 9;
108	                }
109	            }
110	            sum += d;
111	            dbl = !dbl;
112	        }
113	        return (10 - (sum % 10)) % 10;
114	    }
115	
116	    /**
117	     * The owner's membership number, formatted {@code <customerCode>-M<YY>} where YY is the last two
118	     * digits of the registrationDate year (e.g. {@code NSW-1A2B3C4D-M26}). Null when either the customer
119	     * code or the registration date is absent.
120	     */
121	    default String membershipNumber(Owner owner) {
122	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
123	            return null;
124	        }
125	        return String.format("%s-M%02d", owner.getCustomerCode(),
126	                owner.getRegistrationDate().getYear() % 100);
127	    }
128	
129	    /**
130	     * The owner's membership level, a number from 1 to 3 assigned on creation. Starts at 1; add 1
131	     * when an email is present; add 1 when the owner's name was unique on creation (namesakeCount is
132	     * 0); capped at 3. Level 4 is reserved for tenure.
133	     */
134	    static int membershipLevel(Owner owner) {
135	        int level = 1;
136	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
137	        if (hasEmail) {
138	            level++;
139	        }
140	        Integer namesakeCount = owner.getNamesakeCount();
141	        if (namesakeCount != null && namesakeCount == 0) {
142	            level++;
143	        }
144	        return Math.min(level, 3);
145	    }
146	
147	    Owner toOwner(OwnerDto ownerDto);
148	
149	    @Mapping(target = "id", ignore = true)
150	    @Mapping(target = "pets", ignore = true)
151	    Owner toOwner(OwnerFieldsDto ownerDto);
152	
153	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
154	
155	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
156	
157	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
158	        OwnerPageDto ownerPageDto = new OwnerPageDto();
159	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
160	        ownerPageDto.setPage(ownerPage.getNumber());
161	        ownerPageDto.setSize(ownerPage.getSize());
162	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
163	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
164	        return ownerPageDto;
165	    }
166	}
