3	import org.junit.jupiter.api.Test;
4	import static org.junit.jupiter.api.Assertions.assertEquals;
5	import static org.junit.jupiter.api.Assertions.assertNotEquals;
6	import tools.jackson.databind.node.ObjectNode;
7	
8	/** household-hash: householdId is deterministic from (lastName, postcode) alone. Asserting the
9	 * exact hash would couple to the internal normalization, so assert the observable contract: same
10	 * lastName+postcode -> same householdId; a different lastName -> a different householdId. */
11	class AcceptanceTest extends AcceptanceBase {
12	
13		@Test
14		void coreSameLastNameAndPostcodeShareHouseholdId() throws Exception {
15			String lastName = uniqueLastName();
16			ObjectNode a = ownerNode();
17			a.put("lastName", lastName);
18			a.put("postcode", "2000");
19			ObjectNode b = ownerNode();
20			b.put("lastName", lastName);
21			b.put("postcode", "2000");
22			b.put("sharesHousehold", true); // same household -> bypass the duplicate block
23			String ha = fetchOwner(createOwnerOk(a)).get("householdId").asText();
24			String hb = fetchOwner(createOwnerOk(b)).get("householdId").asText();
25			assertEquals(ha, hb);
26	
27			ObjectNode c = ownerNode(); // different lastName, same postcode
28			c.put("postcode", "2000");
29			String hc = fetchOwner(createOwnerOk(c)).get("householdId").asText();
30			assertNotEquals(ha, hc);
31		}
32	}
