12	public class BuildOwner {
13	
14	    public void service(@Val OwnerFieldsDto request, OwnerMapper ownerMapper, Out<Owner> built)
15	            throws FutureRegistrationDateException {
16	        Owner owner = ownerMapper.toOwner(request);
17	        LocalDate effective = owner.getRegistrationDate();
18	        if (effective == null) {
19	            effective = LocalDate.now();
20	        }
21	        // A supplied registration date cannot be in the future; reject a date later than the
22	        // server's current date with a 400 before it is rolled onto a business day.
23	        else if (effective.isAfter(LocalDate.now())) {
24	            throw new FutureRegistrationDateException(effective);
25	        }
26	        // The effective registration date must fall on a business day, whether supplied in the
27	        // request or defaulted to the server date; a weekend rolls forward to the next Monday.
28	        owner.setRegistrationDate(BusinessDays.rollForward(effective));
29	        built.set(owner);
30	    }
31	}
